sys_script_include.script:
var ClaudeApiClient = Class.create();
ClaudeApiClient.prototype = {
    initialize: function() {
        this.constants = new x_agiro_ai_disc_cl.ClaudeDiscoveryConstants();
        this.baseUrl = this.constants.BASE_URL;
        this.apiVersion = this.constants.API_VERSION;
    },

    // ========== Admin API Methods ==========

    /**
     * Get organization info.
     * @returns {{ success: boolean, data?: object, error?: string }}
     */
    getOrgInfo: function() {
        return this._makeAdminRequest(this.constants.ENDPOINTS.ORG_INFO);
    },

    /**
     * Get organization members with pagination.
     * @param {number} [limit] - Max records per page
     * @param {string} [afterId] - Cursor for pagination
     * @returns {{ success: boolean, data?: object, error?: string }}
     */
    getMembers: function(limit, afterId) {
        var params = {};
        if (limit) params.limit = limit;
        if (afterId) params.after_id = afterId;
        return this._makeAdminRequest(this.constants.ENDPOINTS.MEMBERS, params);
    },

    /**
     * Get Claude Code usage report for a single day.
     * @param {string} startDate - YYYY-MM-DD format
     * @param {string} [page] - Pagination cursor
     * @returns {{ success: boolean, data?: object, error?: string }}
     */
    getClaudeCodeUsage: function(startDate, page) {
        var params = { starting_at: this._toDateOnly(startDate) };
        if (page) params.page = page;
        return this._makeAdminRequest(this.constants.ENDPOINTS.CC_USAGE, params);
    },

    /**
     * Get Messages API usage report.
     * @param {string} startDate - RFC 3339 timestamp
     * @param {string} [endDate] - RFC 3339 timestamp
     * @param {string} [bucketWidth] - '1d', '1h', or '1m' (default '1d')
     * @param {string} [page] - Pagination cursor
     * @returns {{ success: boolean, data?: object, error?: string }}
     */
    getMessagesUsage: function(startDate, endDate, bucketWidth, page) {
        var params = {
            starting_at: startDate,
            bucket_width: bucketWidth || '1d',
            'group_by[]': 'model',
        };
        if (endDate) params.ending_at = endDate;
        if (page) params.page = page;
        return this._makeAdminRequest(this.constants.ENDPOINTS.MSG_USAGE, params);
    },

    /**
     * Get cost report.
     * @param {string} startDate - RFC 3339 timestamp
     * @param {string} [endDate] - RFC 3339 timestamp
     * @returns {{ success: boolean, data?: object, error?: string }}
     */
    getCostReport: function(startDate, endDate) {
        var params = { starting_at: startDate };
        if (endDate) params.ending_at = endDate;
        return this._makeAdminRequest(this.constants.ENDPOINTS.COST_REPORT, params);
    },

    // ========== Enterprise Analytics Methods ==========

    /**
     * Get per-user analytics data.
     * @param {string} date - YYYY-MM-DD format
     * @param {string} [page] - Pagination cursor
     * @returns {{ success: boolean, data?: object, error?: string }}
     */
    getAnalyticsUsers: function(date, page) {
        var params = { date: this._toDateOnly(date), limit: 1000 };
        if (page) params.page = page;
        return this._makeAnalyticsRequest(this.constants.ENDPOINTS.ANALYTICS_USERS, params);
    },

    /**
     * Get activity summaries (DAU/WAU/MAU).
     * @param {string} startDate - YYYY-MM-DD
     * @param {string} [endDate] - YYYY-MM-DD
     * @returns {{ success: boolean, data?: object, error?: string }}
     */
    getAnalyticsSummaries: function(startDate, endDate) {
        var params = { starting_date: this._toDateOnly(startDate) };
        if (endDate) params.ending_date = this._toDateOnly(endDate);
        return this._makeAnalyticsRequest(this.constants.ENDPOINTS.ANALYTICS_SUMMARIES, params);
    },

    /**
     * Get skill adoption data.
     * @param {string} date - YYYY-MM-DD
     * @param {string} [page] - Pagination cursor
     * @returns {{ success: boolean, data?: object, error?: string }}
     */
    getAnalyticsSkills: function(date, page) {
        var params = { date: this._toDateOnly(date), limit: 1000 };
        if (page) params.page = page;
        return this._makeAnalyticsRequest(this.constants.ENDPOINTS.ANALYTICS_SKILLS, params);
    },

    /**
     * Get connector/MCP adoption data.
     * @param {string} date - YYYY-MM-DD
     * @param {string} [page] - Pagination cursor
     * @returns {{ success: boolean, data?: object, error?: string }}
     */
    getAnalyticsConnectors: function(date, page) {
        var params = { date: this._toDateOnly(date), limit: 1000 };
        if (page) params.page = page;
        return this._makeAnalyticsRequest(this.constants.ENDPOINTS.ANALYTICS_CONNECTORS, params);
    },

    // ========== Pagination Helper ==========

    /**
     * Auto-paginate through all results for a given request function.
     * @param {function} requestFn - Function(page) that returns { success, data: { data: [], has_more, next_page } }
     * @returns {Array} All data items concatenated
     */
    paginateAll: function(requestFn) {
        var allData = [];
        var page = null;
        var hasMore = true;

        while (hasMore) {
            var response = requestFn.call(this, page);
            if (!response.success) {
                gs.error('[ClaudeApiClient] Pagination failed: ' + response.error);
                break;
            }

            var data = response.data;
            if (data.data && data.data.length > 0) {
                allData = allData.concat(data.data);
            }

            hasMore = data.has_more === true;
            page = data.next_page || null;
        }

        return allData;
    },

    // ========== HTTP Request Methods ==========

    /**
     * Make an authenticated GET request to the Anthropic Admin API.
     * Resolves credentials via the Connection & Credential Alias.
     */
    _makeAdminRequest: function(endpoint, params) {
        var apiKey = this._resolveCredential('admin');
        if (!apiKey) {
            return { success: false, error: 'Anthropic Admin credential not configured. Create a Connection record binding the "' + this.constants.ADMIN_CONNECTION_ALIAS_ID + '" alias to an api_key_credentials record (Admin API key, sk-ant-admin01-...) via Connections & Credentials module.' };
        }
        return this._doRequest(endpoint, params, apiKey);
    },

    /**
     * Make an authenticated GET request to the Enterprise Analytics API.
     * Uses the ANALYTICS_CONNECTION_ALIAS_ID alias. Falls back to the admin alias
     * if the analytics alias is not yet configured — preserves backwards
     * compatibility for installs where the steward has only provisioned one key.
     */
    _makeAnalyticsRequest: function(endpoint, params) {
        var apiKey = this._resolveCredential('analytics');
        if (!apiKey) {
            // Fallback to admin key — keeps older single-key installs working
            apiKey = this._resolveCredential('admin');
        }
        if (!apiKey) {
            return { success: false, error: 'Anthropic Analytics credential not configured. Create a Connection record binding the "' + this.constants.ANALYTICS_CONNECTION_ALIAS_ID + '" alias to an api_key_credentials record via Connections & Credentials module.' };
        }
        return this._doRequest(endpoint, params, apiKey);
    },

    /**
     * Resolve the API key for a given role ('admin' or 'analytics').
     * Each role caches independently so both keys can coexist.
     *
     * Resolution order:
     *   1. sn_cc.ConnectionInfoProvider via the alias binding (preferred)
     *   2. Fallback — sys_connection + api_key_credentials GlideRecord lookup
     *
     * @param {'admin'|'analytics'} role
     * @returns {string|null}
     */
    _resolveCredential: function(role) {
        if (!this._cachedApiKeys) this._cachedApiKeys = {};
        if (this._cachedApiKeys[role]) return this._cachedApiKeys[role];

        var aliasId = (role === 'analytics')
            ? this.constants.ANALYTICS_CONNECTION_ALIAS_ID
            : this.constants.ADMIN_CONNECTION_ALIAS_ID;

        var aliasSysId = this._getAliasSysId(aliasId);
        if (!aliasSysId) return null;

        // Method 1: sn_cc.ConnectionInfoProvider
        try {
            var provider = new sn_cc.ConnectionInfoProvider();
            var connectionInfo = null;
            if (typeof provider.getConnectionInfo === 'function') {
                connectionInfo = provider.getConnectionInfo(aliasSysId);
            } else if (typeof provider.getConnectionInfos === 'function') {
                var infos = provider.getConnectionInfos(aliasSysId);
                if (infos && infos.length > 0) connectionInfo = infos[0];
            }
            if (connectionInfo) {
                var apiKey = connectionInfo.getCredentialAttribute('api_key');
                if (apiKey) {
                    this._cachedApiKeys[role] = apiKey;
                    return apiKey;
                }
            }
        } catch (e) {
            gs.warn('[ClaudeApiClient] sn_cc.ConnectionInfoProvider failed for ' + role + ' alias: ' + e.message);
        }

        // Method 2: sys_connection fallback
        try {
            var connGr = new GlideRecord('sys_connection');
            connGr.addQuery('connection_alias', aliasSysId);
            connGr.setLimit(1);
            connGr.query();
            if (connGr.next()) {
                var credSysId = connGr.getValue('credential');
                if (credSysId) {
                    var credGr = new GlideRecord('api_key_credentials');
                    if (credGr.get(credSysId)) {
                        var key = credGr.getValue('api_key');
                        if (key) {
                            this._cachedApiKeys[role] = key;
                            return key;
                        }
                    }
                }
            }
        } catch (e) {
            gs.warn('[ClaudeApiClient] sys_connection fallback failed for ' + role + ' alias: ' + e.message);
        }

        gs.warn('[ClaudeApiClient] No credential found for ' + role + ' alias: ' + aliasId);
        return null;
    },

    /**
     * @deprecated Use _resolveCredential('admin') instead. Kept for any external callers.
     */
    _resolveCredentialFromAlias: function() {
        return this._resolveCredential('admin');
    },

    /**
     * Get the sys_id of a Connection & Credential Alias by its ID string.
     * @param {string} [aliasId] - Optional alias ID string; defaults to the admin alias.
     * @returns {string|null}
     */
    _getAliasSysId: function(aliasId) {
        var targetAliasId = aliasId || this.constants.ADMIN_CONNECTION_ALIAS_ID;

        if (!this._aliasSysIdCache) this._aliasSysIdCache = {};
        if (this._aliasSysIdCache[targetAliasId]) return this._aliasSysIdCache[targetAliasId];

        // Property override applies only to the admin alias (legacy behaviour)
        if (targetAliasId === this.constants.ADMIN_CONNECTION_ALIAS_ID) {
            var override = gs.getProperty(this.constants.PROPERTY.CONNECTION_ALIAS);
            if (override) {
                this._aliasSysIdCache[targetAliasId] = override;
                return override;
            }
        }

        var gr = new GlideRecord('sys_alias');
        gr.addQuery('id', targetAliasId);
        gr.setLimit(1);
        gr.query();
        if (gr.next()) {
            this._aliasSysIdCache[targetAliasId] = gr.getUniqueValue();
            return this._aliasSysIdCache[targetAliasId];
        }

        gs.warn('[ClaudeApiClient] Connection alias not found: ' + targetAliasId);
        return null;
    },

    /**
     * Core HTTP GET request.
     */
    _doRequest: function(endpoint, params, apiKey) {
        try {
            var url = this._buildUrl(endpoint, params);

            var rm = new sn_ws.RESTMessageV2();
            rm.setEndpoint(url);
            rm.setHttpMethod('GET');
            rm.setRequestHeader('x-api-key', apiKey);
            rm.setRequestHeader('anthropic-version', this.apiVersion);
            rm.setRequestHeader('Content-Type', 'application/json');

            var response = rm.execute();
            var statusCode = response.getStatusCode();
            var body = response.getBody();

            if (statusCode == 200) {
                return { success: true, data: JSON.parse(body) };
            } else {
                gs.error('[ClaudeApiClient] HTTP ' + statusCode + ': ' + body);
                return { success: false, error: 'HTTP ' + statusCode + ': ' + body };
            }
        } catch (e) {
            gs.error('[ClaudeApiClient] Request failed: ' + e.message);
            return { success: false, error: 'Exception: ' + e.message };
        }
    },

    /**
     * Build a full URL with query string parameters.
     */
    _buildUrl: function(endpoint, params) {
        var url = this.baseUrl + endpoint;
        if (params) {
            var parts = [];
            for (var key in params) {
                if (params.hasOwnProperty(key)) {
                    parts.push(encodeURIComponent(key) + '=' + encodeURIComponent(params[key]));
                }
            }
            if (parts.length > 0) {
                url += '?' + parts.join('&');
            }
        }
        return url;
    },

    /**
     * Strip time portion from a date string, returning YYYY-MM-DD.
     */
    _toDateOnly: function(dateStr) {
        if (!dateStr) return '';
        return dateStr.substring(0, 10);
    },

    type: 'ClaudeApiClient'
};
